// LoadJobSystemUpdateJob loads the systemUpdateJobEvent's JobSystemUpdateJob into the .R struct
func (os SystemUpdateJobEventSlice) LoadJobSystemUpdateJob(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	systemUpdateJobs, err := os.JobSystemUpdateJob(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		o.R.JobSystemUpdateJob = nil
		o.R.Loaded.JobSystemUpdateJob = true
	}
	// O(N+M) stitch via a map keyed by the join column (key -> []parent; was O(N*M)).
	systemUpdateJobEventByKey := make(map[string][]*SystemUpdateJobEvent, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}

		systemUpdateJobEventByKey[o.JobID] = append(systemUpdateJobEventByKey[o.JobID], o)
	}

	for _, rel := range systemUpdateJobs {

		owners, ok := systemUpdateJobEventByKey[rel.ID]
		if !ok {
			continue
		}

		for _, o := range owners {

			// to-one: keep only the first matching child (matches the previous break)
			if o.R.JobSystemUpdateJob != nil {
				continue
			}

			rel.R.JobSystemUpdateJobEvents = append(rel.R.JobSystemUpdateJobEvents, o)

			o.R.JobSystemUpdateJob = rel

		}
	}

	return nil
}

